import java.io.DataInputStream

class FastReader(stream: java.io.InputStream) {
    private val BUFFER_SIZE = 1 shl 16
    private val din = DataInputStream(stream)
    private val buffer = ByteArray(BUFFER_SIZE)
    private var bufferPointer = 0
    private var bytesRead = 0

    private fun read(): Byte {
        if (bufferPointer == bytesRead) fillBuffer()
        return buffer[bufferPointer++]
    }

    private fun fillBuffer() {
        bytesRead = din.read(buffer, 0, BUFFER_SIZE)
        bufferPointer = 0
        if (bytesRead == -1) {
            bytesRead = 0
            buffer[0] = -1
        }
    }

    fun nextInt(): Int {
        var ret = 0
        var b = read()
        while (b <= ' '.code.toByte()) b = read()
        val neg = b == '-'.code.toByte()
        if (neg) b = read()
        while (b >= '0'.code.toByte() && b <= '9'.code.toByte()) {
            ret = ret * 10 + (b - '0'.code.toByte())
            b = read()
        }
        return if (neg) -ret else ret
    }

    fun nextToken(): String {
        var b = read()
        while (b <= ' '.code.toByte()) b = read()
        val sb = StringBuilder()
        while (b > ' '.code.toByte()) {
            sb.append(b.toInt().toChar())
            b = read()
        }
        return sb.toString()
    }
}

val dx = intArrayOf(1, -1, 0, 0)
val dy = intArrayOf(0, 0, 1, -1)
const val INF = 1000000000

var n = 0
var m = 0
var sx = 0
var sy = 0
val tx = IntArray(10)
val ty = IntArray(10)
val tp = IntArray(10)
var tn = 0
val bx = IntArray(10)
val by = IntArray(10)
var bn = 0
val pr = IntArray(256)
var ans = 0
val qx = IntArray(2000010)
val qy = IntArray(2000010)
val qt = IntArray(2000010)
val qb = IntArray(2000010)
var l = 0
var r = 0
val a = Array(51) { CharArray(51) }

fun main() {
    val fr = FastReader(System.`in`)
    n = fr.nextInt()
    m = fr.nextInt()
    for (i in 1..n) {
        val s = fr.nextToken()
        for (j in 1..s.length) a[i][j] = s[j - 1]
    }
    for (i in 1..n)
        for (j in 1..m) {
            if (a[i][j] == 'S') {
                sx = i; sy = j
            }
            if (a[i][j] >= '0' && a[i][j] <= '9') {
                tx[a[i][j] - '0'] = i; ty[a[i][j] - '0'] = j; tn++
            }
            if (a[i][j] == 'B') {
                bx[++bn] = i; by[bn] = j
            }
        }
    for (i in 1..tn) tp[i] = fr.nextInt()

    val f = Array(21) { Array(21) { Array(256) { IntArray(256) } } }

    for (i in 1..n)
        for (j in 1..m)
            for (k in 0 until (1 shl tn))
                for (t in 0 until (1 shl bn))
                    f[i][j][k][t] = INF

    l = 1; r = 1
    qx[1] = sx; qy[1] = sy; qt[1] = 0; qb[1] = 0
    f[sx][sy][0][0] = 0
    while (l <= r) {
        val ox = qx[l]
        val oy = qy[l]
        val ot = qt[l]
        val ob = qb[l]
        l++
        for (k in 0 until 4) {
            val nx = ox + dx[k]
            val ny = oy + dy[k]
            var nt = ot
            var nb = ob
            if (a[nx][ny] != '.' && a[nx][ny] != 'S') continue
            for (i in 1..tn) {
                if (ny <= ty[i]) continue
                if (nx == tx[i] - 1 && ox == tx[i]) nt = nt xor (1 shl (i - 1))
                if (ox == tx[i] - 1 && nx == tx[i]) nt = nt xor (1 shl (i - 1))
            }
            for (i in 1..bn) {
                if (ny <= by[i]) continue
                if (nx == bx[i] - 1 && ox == bx[i]) nb = nb xor (1 shl (i - 1))
                if (ox == bx[i] - 1 && nx == bx[i]) nb = nb xor (1 shl (i - 1))
            }
            if (f[nx][ny][nt][nb] > f[ox][oy][ot][ob] + 1) {
                f[nx][ny][nt][nb] = f[ox][oy][ot][ob] + 1
                r++
                qx[r] = nx; qy[r] = ny; qt[r] = nt; qb[r] = nb
            }
        }
    }
    for (i in 0 until (1 shl tn))
        for (j in 1..tn)
            if ((i and (1 shl (j - 1))) != 0) pr[i] += tp[j]
    for (i in 0 until (1 shl tn))
        ans = maxOf(ans, pr[i] - f[sx][sy][i][0])
    println(ans)
}
